(function(root){
  const split=(total,ids)=>{if(!Number.isSafeInteger(total)||total<1||!ids.length)throw Error('Jumlah dan ahli diperlukan.');const base=Math.floor(total/ids.length),extra=total%ids.length;return ids.map((id,i)=>({member:id,amount:base+(i<extra?1:0)}));};
  const paid=(s,id)=>s.payments.filter(p=>p.charge===id&&p.status==='approved').reduce((n,p)=>n+p.amount,0);
  const pending=(s,id)=>s.payments.filter(p=>p.charge===id&&p.status==='pending').reduce((n,p)=>n+p.amount,0);
  const balance=(s,c)=>Math.max(0,c.amount-paid(s,c.id));
  const available=(s,c)=>Math.max(0,balance(s,c)-pending(s,c.id));
  const moneyInput=v=>{if(!/^\d+(\.\d{1,2})?$/.test(String(v)))throw Error('Masukkan jumlah dengan maksimum dua tempat perpuluhan.');const n=Math.round(Number(v)*100);if(!Number.isSafeInteger(n)||n<=0||n>100000000)throw Error('Jumlah mestilah lebih RM0 dan tidak melebihi RM1,000,000.');return n;};
  const record=(s,{charge,amount,method,reference})=>{const c=s.charges.find(x=>x.id===charge);if(!c||!Number.isSafeInteger(amount)||amount<=0||amount>available(s,c))throw Error('Jumlah melebihi baki yang belum dibayar atau sudah menunggu semakan.');if(!['Bank transfer','DuitNow','E-wallet','Cash'].includes(method))throw Error('Kaedah bayaran tidak sah.');const p={id:crypto.randomUUID(),charge,amount,method,reference:String(reference||'').trim().slice(0,160),status:'pending',date:new Date().toISOString()};s.payments.push(p);return p;};
  const approve=(s,id)=>{const p=s.payments.find(x=>x.id===id);if(!p||p.status!=='pending')throw Error('Bayaran ini sudah diproses.');const c=s.charges.find(x=>x.id===p.charge);if(!c||p.amount>balance(s,c))throw Error('Bayaran melebihi baki caj.');p.status='approved';p.reviewed=new Date().toISOString();return p;};
  const cycle=(s,sub,period,due)=>{if(!/^\d{4}-\d{2}$/.test(period)||!/^\d{4}-\d{2}-\d{2}$/.test(due))throw Error('Tempoh dan tarikh perlu sah.');if(s.charges.some(c=>c.subscription===sub.id&&c.period===period))throw Error('Caj untuk kitaran ini sudah wujud.');const shares=split(sub.price,sub.members);shares.forEach(x=>s.charges.push({id:crypto.randomUUID(),subscription:sub.id,member:x.member,payee:sub.payer,amount:x.amount,period,due,self:x.member===sub.payer}));};
  const api={split,paid,pending,balance,available,moneyInput,record,approve,cycle};if(typeof module!=='undefined')module.exports=api;else root.Ledger=api;
})(globalThis);
